# ── Numele firmei, curățat înainte de a ajunge în iDempiere ────────────────────────────────────
# Denumirile din SAGA/ANAF vin cu ghilimele tipografice și cu sedile în loc de virgule dedesubt:
# «ASOCIAŢIA "ROMANIAN SOUL ENTITY"». Validarea veche (`^[\w .,&'\-]{2,80}$`) le respingea, iar
# crearea firmei se oprea cu «parametri invalizi» — fără ca omul să poată face ceva. Ghilimelele
# n-au ce căuta oricum într-un `AD_Client.Name` (60 de caractere, folosit în antetul documentelor
# și în e-Factura), iar Ţ/Ş cu SEDILĂ sunt forma greșită a limbii române încă din 1993: standardul
# cere virgulă dedesubt (Ț/Ș). Deci curățăm, nu refuzăm.
_NUME_SEDILA = {"Ţ": "Ț", "ţ": "ț", "Ş": "Ș", "ş": "ș"}
# ghilimelele (drepte și tipografice) + apostrofurile „inteligente" → afară, respectiv apostrof drept
_NUME_GHILIMELE = "\"„”“«»‟＂❝❞〝〞"
_NUME_APOSTROF = {"’": "'", "‘": "'", "‛": "'", "´": "'", "`": "'"}
# limita REALĂ a coloanei: `select character_maximum_length … ad_client.name` → 60
NUME_FIRMA_MAX = 60
_NUME_VALID = re.compile(r"^[\w .,&'()\-]{2,%d}$" % NUME_FIRMA_MAX, re.UNICODE)


def normalizeaza_nume_firma(nume: str, limita: int = NUME_FIRMA_MAX) -> str:
    """Denumirea, adusă la forma pe care o acceptă și o afișează corect iDempiere.

    Ghilimelele se ELIMINĂ (nu se înlocuiesc cu spațiu: «ASOCIAŢIA "X"» → «ASOCIAȚIA X»),
    sedilele devin virgule dedesubt, apostrofurile tipografice devin apostrof drept, spațiile
    multiple se comprimă, iar rezultatul se taie la limita coloanei, pe cuvânt când se poate.
    Idempotentă: aplicată de două ori dă același rezultat.
    """
    if not nume:
        return ""
    t = unicodedata.normalize("NFC", str(nume))
    for vechi, nou in _NUME_SEDILA.items():
        t = t.replace(vechi, nou)
    for vechi, nou in _NUME_APOSTROF.items():
        t = t.replace(vechi, nou)
    t = "".join(c for c in t if c not in _NUME_GHILIMELE)
    # orice caracter de control sau de spațiere exotică devine spațiu simplu
    t = "".join(" " if unicodedata.category(c)[0] in ("C", "Z") else c for c in t)
    # NU tăiem punctuația de la capete în cazul general: «S.C. … S.R.L.» își pierdea punctul
    t = re.sub(r"\s+", " ", t).strip()
    t = re.sub(r"[\s,;\-]+$", "", t)          # virgula/linia rămasă la coadă după curățare
    if len(t) > limita:
        taiat = t[:limita]
        # tăiem pe ultimul spațiu, ca să nu rămână un cuvânt frânt la jumătate
        if " " in taiat[limita // 2:]:
            taiat = taiat[:taiat.rindex(" ")]
        t = taiat.strip(" .,-")
    return t


def nume_firma_valid(nume: str) -> bool:
    """Numele NORMALIZAT e acceptabil pentru `AD_Client.Name`? (litere unicode, cifre, spații,
    `. , & ' ( ) -`). Se cheamă DUPĂ {@code normalizeaza_nume_firma}, niciodată înaintea ei."""
    return bool(_NUME_VALID.match(nume or ""))


