@app.route("/app/api/saga/bootstrap/stream")
@require_login
def eva_api_saga_bootstrap_stream():
    import re as _re
    cui = (request.args.get("cui") or "").strip()
    name_brut = (request.args.get("name") or "").strip()
    schema = (request.args.get("schema") or "").strip()
    dry = request.args.get("dry") in ("1", "true", "yes")
    # denumirea vine din arhivă sau de la ANAF, cu ghilimele și sedile: se CURĂȚĂ, nu se refuză
    name = normalizeaza_nume_firma(name_brut)

    def _err(msg):
        return ("data: " + json.dumps({"t": "log", "line": msg}) + "\n\n"
                "data: " + json.dumps({"t": "done", "exit": -1}) + "\n\n").encode()

    if not (cui and name and schema):
        return Response(_err("[EROARE] cui + name + schema sunt obligatorii"),
                        mimetype="text/event-stream")
    if not _re.match(r"^[A-Za-z0-9]{2,20}$", cui) or not _re.match(r"^saga_[a-z0-9_]{2,40}$", schema):
        return Response(_err("[EROARE] parametri invalizi (cui/schema)"),
                        mimetype="text/event-stream")
    if not nume_firma_valid(name):
        return Response(_err("[EROARE] denumirea «" + name_brut + "» nu poate fi folosită ca nume"
                             " de firmă nici după curățare (rămâne: «" + name + "»)"),
                        mimetype="text/event-stream")
    args = ["python3", "-u", _BOOTSTRAP_SCRIPT, "--cui", cui, "--name", name, "--schema", schema]
    # RUTARE PER-CABINET: dacă managerul are un cabinet cu instanță PROPRIE (ready), creează firma ÎN
    # ACEA instanță (--idempiere-url + --db-host), nu în cea PARTAJATĂ. Fără cabinet → partajat (compat).
    # FAIL-LOUD: dacă managerul ARE cabinet (slug) dar NU e încă „ready", NU cădem tăcut pe partajat —
    # asta ar crea firma în instanța greșită (client fantomă), iar f1→f8 (care rutează la cabinet) ar
    # da apoi „nu are org activ". Mai bine oprim aici și cerem reîncercarea după provizionare.
    try:
        _sc = (request.args.get("super_cab") or "").strip()
        ci = _eva_get("/saga/cabinet-instance" + (f"?managing_uuid={_sc}" if _sc and _SUPER_CAB_RE.match(_sc) else "")) or {}
    except Exception:  # noqa: BLE001
        ci = {}
    if ci.get("slug"):
        if ci.get("idmp_status") == "ready" and ci.get("idmp_url"):
            args += ["--idempiere-url", ci["idmp_url"], "--db-host", ci["pg_container"]]
            # N144: maparea CUI→client e PER-CABINET; îi dăm bootstrap-ului cabinetul sesiunii, ca
            # rândul (managing_uuid, CUI) să fie scris/actualizat pe cabinetul corect, nu global.
            if ci.get("managing_uuid"):
                args += ["--managing-uuid", ci["managing_uuid"]]
        else:
            return Response(_err(
                f"[EROARE] cabinetul «{ci.get('slug')}» încă nu e gata (status="
                f"{ci.get('idmp_status') or 'necunoscut'}). NU inițializez firma în instanța partajată "
                "(ar ajunge client fantomă, iar F1 ar da «nu are org activ»). Reîncearcă după ce "
                "instanța cabinetului e «ready»."), mimetype="text/event-stream")
    if dry:
        args.append("--dry-run")

    def gen():
        import queue as _q
        import threading as _th
        yield ("data: " + json.dumps({"t": "start", "cmd": " ".join(args)}) + "\n\n").encode()
        if name != name_brut:
            yield ("data: " + json.dumps({"t": "log", "line":
                   "numele din arhivă a fost curățat: «" + name_brut + "» → «" + name + "»"})
                   + "\n\n").encode()
        try:
            p = subprocess.Popen(args, cwd=os.path.dirname(_BOOTSTRAP_SCRIPT),
                                 stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                 text=True, bufsize=1, env=os.environ.copy())
            q = _q.Queue()

            def _rd():
                try:
                    for line in p.stdout:
                        q.put(("log", line.rstrip("\n")))
                finally:
                    q.put(("eof", None))
            _th.Thread(target=_rd, daemon=True).start()
            while True:
                try:
                    kind, val = q.get(timeout=8)
                except _q.Empty:
                    yield ("data: " + json.dumps({"t": "ping"}) + "\n\n").encode()  # heartbeat real (8s)
                    continue
                if kind == "eof":
                    break
                yield ("data: " + json.dumps({"t": "log", "line": val}) + "\n\n").encode()
            p.wait()
            yield ("data: " + json.dumps({"t": "done", "exit": p.returncode}) + "\n\n").encode()
        except Exception as e:  # noqa: BLE001
            yield _err(f"[EROARE runner] {e}")

    return Response(stream_with_context(gen()), mimetype="text/event-stream",
                    headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


