def _sse_proxy(path_with_qs):
    """Proxy STREAMING (SSE) generic către eva-api (injectează Bearer; retransmite liniile live)."""
    import urllib.request as _u
    req = _u.Request(f"{EVA_API}{path_with_qs}", method="GET")
    tok = current_token()
    if tok:
        req.add_header("Authorization", f"Bearer {tok}")

    def gen():
        try:
            with _u.urlopen(req, timeout=3600) as r:
                for line in r:
                    yield line
        except _urlreq.HTTPError as e:
            body = ""
            try:
                body = e.read().decode()[:300]
            except Exception:  # noqa: BLE001
                pass
            yield ("data: " + json.dumps({"t": "log", "line": f"[EROARE {e.code}] {body}"}) + "\n\n").encode()
            yield ("data: " + json.dumps({"t": "done", "exit": -1}) + "\n\n").encode()
        except Exception as e:  # noqa: BLE001
            yield ("data: " + json.dumps({"t": "log", "line": f"[EROARE proxy] {e}"}) + "\n\n").encode()
            yield ("data: " + json.dumps({"t": "done", "exit": -1}) + "\n\n").encode()

    return Response(stream_with_context(gen()), mimetype="text/event-stream",
                    headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


