def _eva_get(path: str, tenant: str | None = None):
    req = _urlreq.Request(f"{EVA_API}{path}")
    # firm-scoping: injectează firma activă pe toate citirile operaționale (eva-api ignoră
    # header-ul pe rutele non-tenant: /tenants, /auth/me).
    cui = tenant if tenant is not None else active_cui()
    if cui:
        req.add_header("X-Tenant-Cui", cui)
    tok = current_token()
    if tok:
        req.add_header("Authorization", f"Bearer {tok}")
    try:
        with _urlreq.urlopen(req, timeout=20) as r:
            return json.load(r)
    except _urlreq.HTTPError as e:
        # PROPAGĂ statusul REAL al backendului (403/404/409/422…), ca `_eva_req`.
        # BUG REPARAT 2026-07-23: `urlopen` aruncă la orice non-2xx, iar excepția necaptată
        # devenea **500** în interfață — pierdeai și codul, și mesajul. Paginile care știu să
        # afișeze `d.error`/`d.detail` primeau o pagină HTML de 500 și nu puteau spune de ce.
        # (Ex. reconciliere fără `?client` → 422 apărea ca 500; `db-access` ca manager → 403 la fel.)
        try:
            payload = e.read()
        except Exception:  # noqa: BLE001
