        return Response(payload or b"{}", status=e.code,
                        mimetype=e.headers.get("Content-Type", "application/json"))


def _me_role_user() -> tuple[str | None, str | None]:
    """(rol, identitate) userului curent din /auth/me — cache pe request (g) ca să nu
    facem un apel suplimentar per proxy. Best-effort; None dacă tokenul lipsește/invalid.
    Tolerează lipsa contextului de request (apeluri în afara Flask) → (None, None)."""
    try:
        if getattr(g, "_eva_role_cache", None) is not None:
            return g._eva_role_cache
    except Exception:  # noqa: BLE001 — fără context request
        return (None, None)
