#
# Cache pe TOKEN (nu pe utilizator, nu global): două sesiuni diferite nu se văd niciodată una
# pe alta, iar cheia e chiar tokenul, deci un token nou (login) sau șters (logout) NU
# nimerește rândul altcuiva. Durata e scurtă cu bună știință — revocarea unei sesiuni se
# simte în cel mult atâtea secunde, iar sondajul de la 2 secunde scade de la ~30 de apeluri
# pe minut la două.
_ME_CACHE: dict[str, tuple[float, dict]] = {}
_ME_CACHE_TTL = float(os.environ.get("EVA_ME_CACHE_TTL", "30") or 30)
_ME_CACHE_MAX = 500


def _me_cache_uita(token: str | None = None) -> None:
    """Uită tokenul dat (logout/login) sau tot cache-ul. Sesiunea nu se ține minte peste ea."""
    if token:
        _ME_CACHE.pop(token, None)
    else:
        _ME_CACHE.clear()


def _current_user_me():
    """Întoarce dict-ul /auth/me (user + access) sau None dacă tokenul e invalid.

    `_eva_get` întoarce un obiect Response la erori upstream (401 „sesiune revocată" etc.) —
    fără verificarea de tip, apelanții (`require_super`, `_managing_uuid`) crăpau cu 500
    pe `.get` în loc să trateze curat lipsa sesiunii.

    Rezultatul POZITIV se memorează pe token {ttl}s (N41). Un răspuns NEGATIV nu se memorează
    niciodată: dacă sesiunea a fost revocată, următoarea cerere trebuie s-o afle imediat.
    """
    token = None
    try:
        token = request.cookies.get("eva_token")
    except Exception:  # noqa: BLE001 — în afara unui request Flask
        token = None
    acum = time.time()
    if token:
        hit = _ME_CACHE.get(token)
        if hit and hit[0] > acum:
            return hit[1]
    try:
        me = _eva_get("/auth/me")
        me = me if isinstance(me, dict) else None
    except Exception:  # noqa: BLE001
        me = None
    if me and token:
        if len(_ME_CACHE) > _ME_CACHE_MAX:      # igienă: nu ținem minte sesiuni moarte la infinit
            for k, v in list(_ME_CACHE.items()):
                if v[0] <= acum:
                    _ME_CACHE.pop(k, None)
        _ME_CACHE[token] = (acum + _ME_CACHE_TTL, me)
    return me


