def _sterge_schema(db: Session, schema: str) -> bool:
    """DROP SCHEMA … CASCADE (PostgreSQL, numele validat de apelant); True dacă schema exista."""
    exists = db.execute(text("select 1 from pg_namespace where nspname=:s"), {"s": schema}).fetchone()
    db.execute(text(f'DROP SCHEMA IF EXISTS "{schema}" CASCADE'))
    db.commit()
def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--cui", required=True)
    ap.add_argument("--name", required=True)
    ap.add_argument("--schema", required=True)
    ap.add_argument("--idempiere-url", default=os.environ.get("IDEMPIERE_URL"),
                    help="webui base al instanței cabinetului (ex. https://eva-idempiere-<slug>:8443); gol=instanța partajată")
    ap.add_argument("--db-host", default=None,
                    help="Postgres al cabinetului (ex. eva-postgres-<slug>); gol=postgres-idempiere partajat")
    ap.add_argument("--managing-uuid", default=os.environ.get("EVA_MANAGING_UUID"),
                    help="cabinetul sesiunii (managing_firms.eva_uuid) — cheia per-cabinet a mapării "
                         "(N144); gol → se derivă din --db-host, altfel rând legacy/partajat")
    ap.add_argument("--dry-run", action="store_true")
    a = ap.parse_args()

    global _IDMP_DB_HOST
    if a.db_host:
        _IDMP_DB_HOST = a.db_host

    # N144: maparea CUI→client e PER-CABINET. managing_uuid vine din sesiune (arg/env); dacă lipsește
    # dar avem --db-host (eva-postgres-<slug>), îl derivăm din managing_firms (cabinetul acelui host).
    managing_uuid = (a.managing_uuid or "").strip() or None
    if not managing_uuid and a.db_host:
        try:
            r = _dbq("select eva_uuid from public.managing_firms where "
                     f"'eva-postgres-'||replace(slug,'_','-') = {_q(a.db_host)} limit 1", eva=True)
            managing_uuid = r[0][0] if r else None
        except Exception:  # noqa: BLE001
            managing_uuid = None
    print(f"[BOOTSTRAP] managing_uuid (cabinet)={managing_uuid or '—(partajat/legacy)'}")

    short = _short(a.name, a.cui)
    org_name = short.upper()
    admin_user = f"{short}_admin"
    normal_user = f"{short}_user"
    print(f"[BOOTSTRAP] cui={a.cui} name={a.name!r} schema={a.schema} org={org_name} "
          f"admin={admin_user} normal={normal_user}")

    def _org_rol(cid: int) -> tuple:
        """Org activ (>0) și rol admin (userlevel C) al clientului `cid` — aceleași interogări ca
        ramura de client nou. Refolosit când maparea trebuie refăcută pentru un client găsit după nume."""
        org = _dbq(f"select ad_org_id from adempiere.ad_org where ad_client_id={cid} and isactive='Y' and ad_org_id<>0 order by ad_org_id")
        role = _dbq(f"select r.ad_role_id from adempiere.ad_role r where r.ad_client_id={cid} and r.userlevel like '%%C%%' order by r.ad_role_id")
        return (int(org[0][0]) if org else None, int(role[0][0]) if role else None)

    def _upsert_map(cid: int, org_id, role_id) -> None:
        """UPSERT (cabinet, CUI) -> client în eva_idempiere_client_map (delete+insert). Refolosit de
        AMBELE ramuri (client nou / client existent găsit după nume). N144: delete-ul e SCOPAT pe
        (managing_uuid, CUI) — NU șterge rândul altui cabinet cu același CUI. Dacă maparea era
        goală/stale, o reface — altfel ruta operare dă 424 EVA-FIRM_NO_ORG."""
        mcol = ",managing_uuid" if managing_uuid else ""
        mval = f",{_q(managing_uuid)}" if managing_uuid else ""
        dele = (f"delete from public.eva_idempiere_client_map where tenant_cui={_q(a.cui)}"
                f"{_managing_clause(managing_uuid)}")
        ins = (f"insert into public.eva_idempiere_client_map (tenant_cui,idempiere_client_id,idempiere_org_id,idempiere_admin_role_id,created_at{mcol}) "
               f"values ({_q(a.cui)},{cid},{org_id or 'null'},{role_id or 'null'},now(){mval})")
        code = (f"import os,psycopg\n"
                f"u=(os.environ.get('EVA_DATABASE_URL') or '').replace('postgresql+psycopg://','postgresql://').replace('+psycopg','')\n"
                f"c=psycopg.connect(u);cur=c.cursor();cur.execute({json.dumps(dele)});cur.execute({json.dumps(ins)});c.commit()")
        subprocess.run(["docker", "exec", EVA_API, "python", "-c", code], capture_output=True, text=True)
        print(f"[BOOTSTRAP] mapare refăcută (cabinet {managing_uuid or '—'}): {a.cui} → client {cid}/org {org_id}/rol {role_id}")

    existing = resolve_existing(a.cui, a.name, managing_uuid)
    if existing:
        print(f"[BOOTSTRAP] AD_Client deja există (sursă={existing['src']}) — nu creez al doilea.")
        cid = int(existing["client"])
        org_id = existing.get("org")
        role_id = existing.get("role")
        # src=name (sau map cu org/rol gol) NU aduce org/rol → le calculăm din instanța țintă,
        # apoi rescriem maparea. Verificarea de identitate din resolve_existing a fost deja trecută.
        if org_id is None or role_id is None:
            o, r = _org_rol(cid)
            org_id = org_id if org_id is not None else o
            role_id = role_id if role_id is not None else r
        _upsert_map(cid, org_id, role_id)
        print(f"[BOOTSTRAP] AD_Client_ID={cid}")
        return 0

    if a.dry_run:
        print(f"[DRY-RUN] ar rula Initial Tenant Setup (nativ) pt '{a.name}' -> AD_Client nou + org {org_name} "
              f"+ user {admin_user} + RON + plan conturi RO. Nimic creat.")
        return 0

